/* eslint-disable react-hooks/exhaustive-deps */
import React, { useCallback, useEffect } from 'react'
import { Alert, Button, Col, DatePicker, Form, Input, message, Row, Select, Spin } from 'antd'
import { FORM_FIELDS } from './constants'
import CustomNumberFormat from '../../../../CommonComponents/CustomNumberFormat'
import { businessDiff, ebFilesAcceptString } from '../../../../utils/helpers'
import moment from 'moment'
import { initialQuotationFromValues, isDateInRange } from './utility'
import { useDownloadFileFromGcs, useLeadConfig, useProviderList } from '../../../../state/hooks'
import { useErrorContextValue, useGet, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useHistory, useParams } from 'react-router'
import { useAddQuotation, useFetchCompanyName, useUpdateQuotation } from '../../../../state/AddNewQuotation/hooks/useAddNewQuotation'
import { QuotationFormValidations } from './validations'
import { AntdUploadFullWidthStyled } from '../../../AddNewCase/containers/components/styles'
import FileUploadOnGcsV2 from '../../../../../../../components/FileUploadOnGcsV2'
import { convertPriceStringToNumber } from '../../../../../../../helpers/utility'
import { addQuotationApiConfig } from '../../apiConfig'

const QuotationForm = ({ form }) => {
  const { getFieldDecorator } = form
  const { downloadRequest } = useDownloadFileFromGcs()
  const history = useHistory()
  const { quotationId } = useParams() || {}
  const caseIdFromState = history?.location?.state?.case_id
  const [quotationDetail, getQuotationDetail] = useGet(addQuotationApiConfig.quotationDetail)
  const { companyNameData, companyNameRequest } = useFetchCompanyName()
  const [{ COMPANY_NAME_LOADER, UPDATE_QUOTATION_LOADER, ADD_QUOTATION_LOADER }] = useLoaderContextValue()
  const [{
    companyNameErrorData,
    COMPANY_NAME_ERROR,
    UPDATE_QUOTATION_ERROR,
    updateQuotationStatus,
    ADD_QUOTATION_ERROR,
    addQuotationErrorData,
    addQuotationStatus,
    updateQuotationErrorData
  }] = useErrorContextValue()
  const { leadConfigData, leadConfigRequest } = useLeadConfig()
  const { updateQuotationData, updateQuotationRequest } = useUpdateQuotation()
  const { addQuotationData, addQuotationRequest } = useAddQuotation()
  const {
    [FORM_FIELDS.REQUEST_FROM_MARKETING]: requestFromMarketingDate,
    [FORM_FIELDS.BOOKING_TO_INSURER]: bookingToInsurerDate,
    [FORM_FIELDS.DATA_SENT_TO_INSURER]: dataSentToInsurerDate,
    [FORM_FIELDS.QUOTATION_RECEIVED_FROM_INSURER]: quotationReceivedFromInsurerDate,
    [FORM_FIELDS.MONEY_IN]: moneyInDate,
    [FORM_FIELDS.CASE_ID]: caseId
  } = form.getFieldsValue()
  const { providerListRequest, providerListData } = useProviderList()
  const [{ PROVIDER_LIST_LOADER }] = useLoaderContextValue()
  const { resetError } = useResetError()

  const handleSubmit = (e) => {
    e.preventDefault()
    form.validateFields((error, values) => {
      if (!error) {
        const toBeSentValues = {
          ...values,
          [FORM_FIELDS.BOOKING_TO_INSURER]: values[FORM_FIELDS.BOOKING_TO_INSURER] && values[FORM_FIELDS.BOOKING_TO_INSURER].format('YYYY-MM-DD'),
          [FORM_FIELDS.DATA_SENT_TO_INSURER]: values[FORM_FIELDS.DATA_SENT_TO_INSURER] && values[FORM_FIELDS.DATA_SENT_TO_INSURER].format('YYYY-MM-DD'),
          [FORM_FIELDS.REQUEST_FROM_MARKETING]: values[FORM_FIELDS.REQUEST_FROM_MARKETING] && values[FORM_FIELDS.REQUEST_FROM_MARKETING].format('YYYY-MM-DD'),
          [FORM_FIELDS.QUOTATION_RECEIVED_FROM_INSURER]: values[FORM_FIELDS.QUOTATION_RECEIVED_FROM_INSURER] && values[FORM_FIELDS.QUOTATION_RECEIVED_FROM_INSURER].format('YYYY-MM-DD'),
          [FORM_FIELDS.MONEY_IN]: values[FORM_FIELDS.MONEY_IN] && values[FORM_FIELDS.MONEY_IN].format('YYYY-MM-DD'),
          [FORM_FIELDS.PREMI_RELEASE_FROM_INSURANCE]: values[FORM_FIELDS.PREMI_RELEASE_FROM_INSURANCE] ? convertPriceStringToNumber(values[FORM_FIELDS.PREMI_RELEASE_FROM_INSURANCE]) : undefined,
          [FORM_FIELDS.DOCUMENTS_RECEIVED]: Array.isArray(values[FORM_FIELDS.DOCUMENTS_RECEIVED])
            ? values[FORM_FIELDS.DOCUMENTS_RECEIVED].map(file => file.url).filter(url => !!url)
            : undefined
        }

        if (quotationDetail?.case_id) {
          updateQuotationRequest({ ...toBeSentValues, id: quotationId })
        } else {
          addQuotationRequest(toBeSentValues)
        }
      }
    })
  }

  const validateDates = useCallback(() => {
    if (form.isFieldsTouched([FORM_FIELDS.BOOKING_TO_INSURER])) {
      form.validateFields([FORM_FIELDS.BOOKING_TO_INSURER])
    }
    if (form.isFieldsTouched([FORM_FIELDS.DATA_SENT_TO_INSURER])) {
      form.validateFields([FORM_FIELDS.DATA_SENT_TO_INSURER])
    }
    if (form.isFieldsTouched([FORM_FIELDS.QUOTATION_RECEIVED_FROM_INSURER])) {
      form.validateFields([FORM_FIELDS.QUOTATION_RECEIVED_FROM_INSURER])
    }
  }, [])

  const handleFileDownload = (file) => {
    resetError(['DOWNLOAD_FILE_FROM_GCS_ERROR'])
    downloadRequest({
      action_type: 'GET',
      identifier: 'quotation',
      file_name: file.name
    })
  }

  useEffect(() => {
    validateDates()
    if (requestFromMarketingDate) {
      const tat1StartDate = requestFromMarketingDate.clone()
      const tat1EndDate = bookingToInsurerDate ? bookingToInsurerDate.clone() : moment()
      form.setFieldsValue({ [FORM_FIELDS.TAT1]: businessDiff(tat1StartDate, tat1EndDate) })
    } else {
      form.resetFields([FORM_FIELDS.TAT1])
    }
    if (bookingToInsurerDate) {
      const tat2StartDate = bookingToInsurerDate.clone()
      const tat2EndDate = dataSentToInsurerDate ? dataSentToInsurerDate.clone() : moment()
      form.setFieldsValue({ [FORM_FIELDS.TAT2]: businessDiff(tat2StartDate, tat2EndDate) })
    } else {
      form.resetFields([FORM_FIELDS.TAT2])
    }
    if (dataSentToInsurerDate) {
      const tat3StartDate = dataSentToInsurerDate.clone()
      const tat3EndDate = quotationReceivedFromInsurerDate ? quotationReceivedFromInsurerDate.clone() : moment()
      form.setFieldsValue({ [FORM_FIELDS.TAT3]: businessDiff(tat3StartDate, tat3EndDate) })
    } else {
      form.resetFields([FORM_FIELDS.TAT3])
    }
  }, [requestFromMarketingDate, bookingToInsurerDate, dataSentToInsurerDate, quotationReceivedFromInsurerDate])

  useEffect(() => {
    validateDates()
  }, [moneyInDate])

  useEffect(() => {
    if (companyNameData && companyNameData.name) {
      form.setFieldsValue({ [FORM_FIELDS.COMPANY_NAME]: companyNameData.name })
    }
  }, [companyNameData])

  useEffect(() => {
    if (COMPANY_NAME_ERROR && companyNameErrorData) {
      const { message } = companyNameErrorData
      form.setFields({
        [FORM_FIELDS.CASE_ID]: {
          value: undefined,
          errors: [new Error(message)]
        },
        [FORM_FIELDS.COMPANY_NAME]: {
          value: undefined
        }
      })
    }
  }, [companyNameErrorData, COMPANY_NAME_ERROR])

  useEffect(() => {
    const timer = setTimeout(() => {
      form.resetFields([FORM_FIELDS.COMPANY_NAME])
      if (caseId) {
        const values = form.getFieldsValue()
        form.setFields({
          [FORM_FIELDS.CASE_ID]: {
            value: values[FORM_FIELDS.CASE_ID],
            error: []
          }
        })
        companyNameRequest({ id: caseId })
      }
    }, 500)
    return () => clearTimeout(timer)
  }, [caseId])

  useEffect(() => {
    if (ADD_QUOTATION_ERROR && addQuotationErrorData) {
      const { error, message: errorMessage } = addQuotationErrorData
      const values = form.getFieldsValue()
      if (errorMessage) {
        message.error(errorMessage)
      }
      form.setFieldsValue()
      for (const key in error) {
        form.setFields({
          [key]: {
            value: values[key],
            errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
          }
        })
      }
    }
  }, [ADD_QUOTATION_ERROR, addQuotationErrorData])

  useEffect(() => {
    if (UPDATE_QUOTATION_ERROR && updateQuotationErrorData) {
      const { error, message: errorMessage } = updateQuotationErrorData
      const values = form.getFieldsValue()
      form.setFieldsValue()
      if (errorMessage) {
        message.error(errorMessage)
      }
      for (const key in error) {
        form.setFields({
          [key]: {
            value: values[key],
            errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
          }
        })
      }
    }
  }, [UPDATE_QUOTATION_ERROR, updateQuotationErrorData])

  useEffect(() => {
    if (updateQuotationData && updateQuotationData.message === 'success') {
      message.success('Quotation Updated Successfully')
      history.push('/employee-benefits/quotation-data-summary')
    }
    if (addQuotationData && addQuotationData.message === 'success') {
      message.success('Quotation Added Successfully')
      history.push('/employee-benefits/quotation-data-summary')
    }
  }, [updateQuotationData, addQuotationData])

  useEffect(() => {
    if (quotationDetail?.case_id) {
      form.setFieldsValue({
        ...initialQuotationFromValues(quotationDetail)
      })
    }
  }, [quotationDetail])

  useEffect(() => {
    providerListRequest()
    leadConfigRequest()
    form.setFieldsValue({
      [FORM_FIELDS.CASE_ID]: caseIdFromState
    })
    if (quotationId) {
      getQuotationDetail({ id: quotationId })
    }
    return () => resetError([
      'ADD_QUOTATION_ERROR',
      'addQuotationErrorData',
      'addQuotationStatus',
      'updateQuotationErrorData',
      'UPDATE_QUOTATION_ERROR',
      'updateQuotationStatus'
    ])
  }, [getQuotationDetail, quotationId])

  return (
    <Spin
      spinning={
        !!PROVIDER_LIST_LOADER ||
        !!COMPANY_NAME_LOADER ||
        !!UPDATE_QUOTATION_LOADER ||
        !!ADD_QUOTATION_LOADER
      }
    >
      <Row gutter={80} type='flex' justify='center'>
        <Col span={20}>
          {ADD_QUOTATION_ERROR && (!addQuotationErrorData) && <Alert type='error' message={addQuotationStatus} banner />}
          {UPDATE_QUOTATION_ERROR && (!updateQuotationErrorData) && <Alert type='error' message={updateQuotationStatus} banner />}
        </Col>
      </Row>
      <Form
        // {...{ labelCol: { xs: 24, sm: 12 }, wrapperCol: { xs: 24, sm: 12 } }}
        onSubmit={handleSubmit}
      >
        <Row gutter={80} type='flex' justify='center'>
          <Col span={10}>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  label='Case Id'
                  required
                >
                  {
                    getFieldDecorator('case_id', {
                      rules: QuotationFormValidations[FORM_FIELDS.CASE_ID]
                    })(
                      <Input disabled={!!(quotationDetail && quotationDetail[FORM_FIELDS.CASE_ID]) || COMPANY_NAME_LOADER} />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  label='Company Name'
                  required
                >
                  {
                    getFieldDecorator(FORM_FIELDS.COMPANY_NAME, {
                      rules: QuotationFormValidations[FORM_FIELDS.COMPANY_NAME]
                    })(
                      <Input
                        readOnly
                        disabled
                      />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  label='Insurance Provider'
                  required
                >
                  {
                    getFieldDecorator(FORM_FIELDS.INSURANCE_PROVIDER, {
                      rules: [
                        {
                          required: true,
                          message: 'Insurance provider is required'
                        }
                      ]
                    })(
                      <Select disabled={quotationDetail?.is_case_in_final_status}>
                        {providerListData && Array.isArray(providerListData.providers) && (
                          providerListData.providers
                            .sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()))
                            .map(provider => (
                              <Select.Option key={provider} value={provider}>
                                {provider}
                              </Select.Option>
                            ))
                        )}
                      </Select>
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  label='Request From Marketing'
                >
                  {
                    getFieldDecorator(FORM_FIELDS.REQUEST_FROM_MARKETING, {
                      rules: [
                        {
                          required: true,
                          message: 'Request From Marketing is required'
                        }
                      ]
                    })(
                      <DatePicker
                        disabledDate={date => !isDateInRange(
                          date,
                          undefined,
                          bookingToInsurerDate || dataSentToInsurerDate || quotationReceivedFromInsurerDate || moneyInDate
                        )}
                      />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  label='TAT1'
                >
                  {
                    getFieldDecorator(FORM_FIELDS.TAT1, {})(
                      <Input readOnly disabled />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  label='Booking To Insurer'
                >
                  {
                    getFieldDecorator(FORM_FIELDS.BOOKING_TO_INSURER, {
                      rules: QuotationFormValidations[FORM_FIELDS.BOOKING_TO_INSURER](dataSentToInsurerDate, quotationReceivedFromInsurerDate, moneyInDate)
                    })(
                      <DatePicker
                        disabledDate={date => !isDateInRange(
                          date,
                          requestFromMarketingDate,
                          dataSentToInsurerDate || quotationReceivedFromInsurerDate || moneyInDate
                        )}
                      />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  label='TAT2'
                >
                  {
                    getFieldDecorator(FORM_FIELDS.TAT2, {})(
                      <Input readOnly disabled />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  label='Data Sent To Insurer'
                >
                  {
                    getFieldDecorator(FORM_FIELDS.DATA_SENT_TO_INSURER, {
                      rules: QuotationFormValidations[FORM_FIELDS.DATA_SENT_TO_INSURER](
                        quotationReceivedFromInsurerDate,
                        moneyInDate
                      )
                    })(
                      <DatePicker
                        disabledDate={date => !isDateInRange(
                          date,
                          bookingToInsurerDate || requestFromMarketingDate,
                          quotationReceivedFromInsurerDate || moneyInDate
                        )}
                      />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
          </Col>
          <Col span={10}>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  label='TAT3'
                >
                  {
                    getFieldDecorator(FORM_FIELDS.TAT3, {})(
                      <Input readOnly disabled />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  label='Quotation Received From Insurer'
                >
                  {
                    getFieldDecorator(FORM_FIELDS.QUOTATION_RECEIVED_FROM_INSURER, {
                      rules: QuotationFormValidations[FORM_FIELDS.QUOTATION_RECEIVED_FROM_INSURER](moneyInDate)
                    })(
                      <DatePicker
                        disabledDate={date => !isDateInRange(date,
                          dataSentToInsurerDate || bookingToInsurerDate || requestFromMarketingDate,
                          moneyInDate
                        )}
                      />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  label='Premium Released From Insurer'
                >
                  {
                    getFieldDecorator(FORM_FIELDS.PREMI_RELEASE_FROM_INSURANCE, {})(
                      <CustomNumberFormat />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  label='Quotation Status'
                  required
                >
                  {
                    getFieldDecorator(FORM_FIELDS.QUOTATION_STATUS, {
                      rules: QuotationFormValidations[FORM_FIELDS.QUOTATION_STATUS]
                    })(
                      <Select disabled={quotationDetail?.is_case_in_final_status}>
                        {
                          leadConfigData?.quotation_status_for_update?.map(({ code, name }) => (
                            <Select.Option key={code} value={code}>{name}</Select.Option>
                          ))
                        }
                      </Select>
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  label='Money In'
                >
                  {
                    getFieldDecorator(FORM_FIELDS.MONEY_IN, {
                    })(
                      <DatePicker
                        disabledDate={date => !isDateInRange(
                          date,
                          quotationReceivedFromInsurerDate || dataSentToInsurerDate || bookingToInsurerDate || requestFromMarketingDate
                        )}
                      />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <AntdUploadFullWidthStyled>
                  <FileUploadOnGcsV2
                    getFieldDecorator={getFieldDecorator}
                    name={FORM_FIELDS.DOCUMENTS_RECEIVED}
                    buttonClassName='fluid-width'
                    form={form}
                    multiple
                    onPreview={handleFileDownload}
                    identifier='quotation'
                    accept={ebFilesAcceptString}
                    formItemProps={{ label: 'Document Received' }}
                    maxSize={15}
                    minSize={0.001}
                  />
                </AntdUploadFullWidthStyled>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  label='Notes'
                >
                  {
                    getFieldDecorator(FORM_FIELDS.NOTES, {})(
                      <Input.TextArea maxLength='300' rows='6' />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <Form.Item
                  hasFeedback
                  {...{ wrapperCol: { xs: { span: 24, offset: 0 }, sm: { span: 12, offset: 12 } } }
                  }
                >
                  <Button
                    type='primary'
                    htmlType='submit'
                    block
                  >
                    Submit
                  </Button>
                </Form.Item>
              </Col>
            </Row>

          </Col>
        </Row>
      </Form>
    </Spin>
  )
}
export default Form.create({ name: 'quotation-form' })(QuotationForm)
