import { FORM_FIELDS } from './constants'
import moment from 'moment'
import { formatIntl } from '../../../../../../../helpers/utility'

export function isDateInRange (date, rangeStart, rangeEnd) {
  if (date.isAfter(undefined, 'day')) return false
  if (!date) return false
  if (!(rangeEnd || rangeStart)) return true
  if (rangeStart && rangeEnd) {
    return date.isBetween(rangeStart, rangeEnd, 'day', '[]')
  }
  if (!rangeStart) {
    return date.isSameOrBefore(rangeEnd, 'day')
  }
  if (!rangeEnd) {
    return date.isSameOrAfter(rangeStart, 'day')
  }
}

export const initialQuotationFromValues = (quotationDataFromState) => ({
  [FORM_FIELDS.CASE_ID]: quotationDataFromState[FORM_FIELDS.CASE_ID],
  [FORM_FIELDS.INSURANCE_PROVIDER]: quotationDataFromState[FORM_FIELDS.INSURANCE_PROVIDER],
  [FORM_FIELDS.REQUEST_FROM_MARKETING]: quotationDataFromState[FORM_FIELDS.REQUEST_FROM_MARKETING] ? moment(quotationDataFromState[FORM_FIELDS.REQUEST_FROM_MARKETING]) : undefined,
  [FORM_FIELDS.BOOKING_TO_INSURER]: quotationDataFromState[FORM_FIELDS.BOOKING_TO_INSURER] ? moment(quotationDataFromState[FORM_FIELDS.BOOKING_TO_INSURER]) : undefined,
  [FORM_FIELDS.DATA_SENT_TO_INSURER]: quotationDataFromState[FORM_FIELDS.DATA_SENT_TO_INSURER] ? moment(quotationDataFromState[FORM_FIELDS.DATA_SENT_TO_INSURER]) : undefined,
  [FORM_FIELDS.QUOTATION_RECEIVED_FROM_INSURER]: quotationDataFromState[FORM_FIELDS.QUOTATION_RECEIVED_FROM_INSURER] ? moment(quotationDataFromState[FORM_FIELDS.QUOTATION_RECEIVED_FROM_INSURER]) : undefined,
  [FORM_FIELDS.MONEY_IN]: quotationDataFromState[FORM_FIELDS.MONEY_IN] ? moment(quotationDataFromState[FORM_FIELDS.MONEY_IN]) : undefined,
  [FORM_FIELDS.PREMI_RELEASE_FROM_INSURANCE]: formatIntl(quotationDataFromState[FORM_FIELDS.PREMI_RELEASE_FROM_INSURANCE]),
  [FORM_FIELDS.QUOTATION_STATUS]: quotationDataFromState[FORM_FIELDS.QUOTATION_STATUS],
  [FORM_FIELDS.NOTES]: quotationDataFromState[FORM_FIELDS.NOTES],
  [FORM_FIELDS.DOCUMENTS_RECEIVED]: Array.isArray(quotationDataFromState[FORM_FIELDS.DOCUMENTS_RECEIVED])
    ? quotationDataFromState[FORM_FIELDS.DOCUMENTS_RECEIVED].map(url => ({
        name: String(url).split(':')[2],
        uid: url,
        url
      }))
    : []
})
