import ebUrls from '../../../../../request/urls/employeeBenefit'

const actions = {

  COMPANY_NAME_REQUEST: 'COMPANY_NAME_REQUEST',
  COMPANY_NAME: 'COMPANY_NAME',
  UPDATE_QUOTATION_REQUEST: 'UPDATE_QUOTATION_REQUEST',
  UPDATE_QUOTATION: 'UPDATE_QUOTATION',
  ADD_QUOTATION_REQUEST: 'ADD_QUOTATION_REQUEST',
  ADD_QUOTATION: 'ADD_QUOTATION',

  fetchCompanyName: (payload) => ({
    type: actions.COMPANY_NAME_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.fetchCompanyName
    }
  }),
  updateQuotation: (payload) => ({
    type: actions.UPDATE_QUOTATION_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.updateQuotation
    }
  }),
  addQuotation: (payload) => ({
    type: actions.ADD_QUOTATION_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.addQuotation
    }
  })
}

export default actions
